/**
 * Submit a crowd report from user check-in
 * PROOF: This function writes to Firestore crowd_reports collection with source="user"
 */
export const submitCrowdReport = async (
  officeId: string,
  crowdLevel: CrowdLevel,
  userId?: string
): Promise<string> => {
  try {
    // Verify db is initialized
    if (!db) {
      throw new Error('Firestore database not initialized. Check Firebase configuration.');
    }

    // Verify user is authenticated (required by security rules)
    if (typeof window !== 'undefined') {
      const { getCurrentUser } = await import('./auth');
      const user = getCurrentUser();
      if (!user) {
        throw new Error('User must be authenticated to submit reports. Please sign in.');
      }
    }

    const timestamp = Date.now();
    const report = {
      officeId,
      crowdLevel,
      timestamp,
      userId: userId || null,
      source: 'user' as ReportSource, // Mark as user-generated report
    };

    console.log('[Firebase] Writing user crowd report to Firestore:', {
      officeId,
      crowdLevel,
      userId: userId || 'anonymous',
      source: 'user',
      timestamp,
      payload: report,
    });

    const reportsRef = collection(db, 'crowd_reports');

    // Validate payload before sending
    if (!officeId || !crowdLevel || !timestamp) {
      throw new Error(`Invalid payload: officeId=${officeId}, crowdLevel=${crowdLevel}, timestamp=${timestamp}`);
    }

    if (!['low', 'medium', 'high'].includes(crowdLevel)) {
      throw new Error(`Invalid crowdLevel: ${crowdLevel}. Must be 'low', 'medium', or 'high'.`);
    }

    const docRef = await addDoc(reportsRef, report);

    console.log('[Firebase] User crowd report written successfully:', {
      reportId: docRef.id,
      officeId,
      source: 'user',
      timestamp: new Date(timestamp).toISOString(),
    });

    return docRef.id;
  } catch (error: any) {
    console.error('[Firebase] Error submitting crowd report:', {
      error: error.message,
      code: error.code,
      stack: error.stack,
      officeId,
      crowdLevel,
      userId,
    });
    throw error; // Re-throw to let caller handle it
  }
};

/**
 * Get recent crowd reports for an office within time window (30-60 minutes)
 * Prioritizes user reports over seed/system reports
 * PROOF: This function queries Firestore crowd_reports collection with time filtering
 */
export const getRecentCrowdReports = async (
  officeId: string,
  timeWindowMinutes: number = 60,
  limitCount: number = 100
): Promise<CrowdReport[]> => {
  const now = Date.now();
  const timeWindowMs = timeWindowMinutes * 60 * 1000;
  const cutoffTime = now - timeWindowMs;

  console.log('[Firebase] Querying Firestore for crowd reports:', { 
    officeId, 
    timeWindowMinutes,
    cutoffTime: new Date(cutoffTime).toISOString(),
    limitCount 
  });

  const reportsRef = collection(db, 'crowd_reports');

  // Firestore requires composite index for multiple where clauses with orderBy
  // Query all reports for office, then filter by time in memory (more reliable)
  const q = query(
    reportsRef,
    where('officeId', '==', officeId),
    orderBy('timestamp', 'desc'),
    limit(limitCount * 2) // Get more to account for time filtering
  );

  const snapshot = await getDocs(q);

  // Filter by time window and ensure source field exists (default to 'user' for backward compatibility)
  const allReports = snapshot.docs
    .map((doc) => {
      const data = doc.data();
      // Handle timestamp: could be number or Firestore Timestamp
      let timestamp: number;
      if (typeof data.timestamp === 'number') {
        timestamp = data.timestamp;
      } else if (data.timestamp?.toMillis) {
        timestamp = data.timestamp.toMillis();
      } else {
        console.warn('[Firebase] Invalid timestamp format in report:', { reportId: doc.id, timestamp: data.timestamp });
        timestamp = Date.now(); // Fallback to current time
      }

      return {
        id: doc.id,
        officeId: data.officeId,
        crowdLevel: data.crowdLevel,
        timestamp: timestamp, // Ensure timestamp is a number
        userId: data.userId || null,
        source: (data.source || 'user') as 'user' | 'seed' | 'system', // Default to 'user' for old reports
      };
    })
    .filter((r) => {
      // Filter by time window - ensure timestamp is valid number
      const isValid = r.timestamp && typeof r.timestamp === 'number' && r.timestamp >= cutoffTime;
      if (!isValid && r.timestamp) {
        const ageMinutes = (Date.now() - r.timestamp) / 1000 / 60;
        console.warn('[Firebase] Report filtered out due to timestamp:', {
          reportId: r.id,
          timestamp: r.timestamp,
          cutoffTime,
          ageMinutes: ageMinutes.toFixed(2),
          timeWindowMinutes,
        });
      }
      return isValid;
    })
    .slice(0, limitCount) as CrowdReport[];

  // Prioritize user reports: put user reports first, then others
  const userReports = allReports.filter(r => r.source === 'user');
  const otherReports = allReports.filter(r => r.source !== 'user');
  const prioritizedReports = [...userReports, ...otherReports];

  console.log('[Firebase] Crowd reports retrieved:', {
    officeId,
    totalReports: allReports.length,
    userReports: userReports.length,
    otherReports: otherReports.length,
    timeWindow: `${timeWindowMinutes} minutes`,
    oldestReport: allReports.length > 0 ? new Date(Math.min(...allReports.map(r => r.timestamp))).toISOString() : 'none',
    newestReport: allReports.length > 0 ? new Date(Math.max(...allReports.map(r => r.timestamp))).toISOString() : 'none',
  });

  return prioritizedReports;
};

import { CrowdLevel, CrowdReport } from '../firebase/firestore';

/**
 * Aggregated crowd data result
 */
export interface AggregatedCrowdData {
  crowdLevel: CrowdLevel;
  averageWaitTime: number;
  reportCount: number;
  lastUpdated: number | null;
  userReportCount: number;
  timeWindowMinutes: number;
}

/**
 * Calculate current crowd level from recent reports
 * Prioritizes user reports over seed/system reports
 * Uses weighted voting: user reports count 2x, others count 1x
 */
export const calculateCrowdLevel = (reports: CrowdReport[]): CrowdLevel => {
  if (reports.length === 0) {
    return 'medium'; // Default to medium if no reports
  }

  // Weighted counts: user reports count 2x, others count 1x
  const counts = {
    low: 0,
    medium: 0,
    high: 0,
  };

  reports.forEach((report) => {
    const weight = report.source === 'user' ? 2 : 1; // User reports have 2x weight
    counts[report.crowdLevel] += weight;
  });

  // Return the most common level
  if (counts.high >= counts.medium && counts.high >= counts.low) {
    return 'high';
  } else if (counts.medium >= counts.low) {
    return 'medium';
  } else {
    return 'low';
  }
};

/**
 * Calculate average wait time from actual reports
 * Uses weighted average: user reports weighted 2x
 */
export const calculateAverageWaitTime = (reports: CrowdReport[]): number => {
  if (reports.length === 0) {
    return 30; // Default to 30 minutes if no reports
  }

  const timeMap: Record<CrowdLevel, number> = {
    low: 10,
    medium: 30,
    high: 60,
  };

  let totalWeightedTime = 0;
  let totalWeight = 0;

  reports.forEach((report) => {
    const weight = report.source === 'user' ? 2 : 1; // User reports weighted 2x
    const waitTime = timeMap[report.crowdLevel];
    totalWeightedTime += waitTime * weight;
    totalWeight += weight;
  });

  return Math.round(totalWeightedTime / totalWeight);
};

/**
 * Estimate waiting time based on crowd level
 * Simple mapping: low=10min, medium=30min, high=60min
 * @deprecated Use calculateAverageWaitTime for more accurate results from actual reports
 */
export const estimateWaitingTime = (crowdLevel: CrowdLevel): number => {
  const timeMap: Record<CrowdLevel, number> = {
    low: 10,
    medium: 30,
    high: 60,
  };
  return timeMap[crowdLevel];
};

/**
 * Aggregate crowd data from reports within time window
 * Computes: crowd level, average wait time, report count, last updated time
 * User reports always override seed/system reports when available
 */
export const aggregateCrowdData = (
  reports: CrowdReport[],
  timeWindowMinutes: number = 60
): AggregatedCrowdData => {
  // Filter reports within time window (already done in getRecentCrowdReports, but double-check)
  const now = Date.now();
  const timeWindowMs = timeWindowMinutes * 60 * 1000;
  const recentReports = reports.filter(r => r.timestamp >= (now - timeWindowMs));

  // Separate user reports from others
  const userReports = recentReports.filter(r => r.source === 'user');
  const otherReports = recentReports.filter(r => r.source !== 'user');

  // If we have user reports, use only those. Otherwise, use all reports.
  const reportsToUse = userReports.length > 0 ? userReports : otherReports;

  console.log('[Aggregation] Aggregating crowd data:', {
    totalReports: recentReports.length,
    userReports: userReports.length,
    otherReports: otherReports.length,
    reportsUsed: reportsToUse.length,
    timeWindow: `${timeWindowMinutes} minutes`,
  });

  const crowdLevel = calculateCrowdLevel(reportsToUse);
  const averageWaitTime = calculateAverageWaitTime(reportsToUse);
  const reportCount = recentReports.length;
  const lastUpdated = getLastUpdatedTime(recentReports);

  return {
    crowdLevel,
    averageWaitTime,
    reportCount,
    lastUpdated,
    userReportCount: userReports.length,
    timeWindowMinutes,
  };
};

/**
 * Get the most recent report timestamp
 */
export const getLastUpdatedTime = (reports: CrowdReport[]): number | null => {
  if (reports.length === 0) {
    return null;
  }
  return Math.max(...reports.map((r) => r.timestamp));
};

/**
 * Format timestamp to human-readable string
 */
export const formatTimestamp = (timestamp: number): string => {
  const date = new Date(timestamp);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMs / 3600000);
  const diffDays = Math.floor(diffMs / 86400000);

  if (diffMins < 1) {
    return 'Just now';
  } else if (diffMins < 60) {
    return `${diffMins} minute${diffMins > 1 ? 's' : ''} ago`;
  } else if (diffHours < 24) {
    return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;
  } else if (diffDays < 7) {
    return `${diffDays} day${diffDays > 1 ? 's' : ''} ago`;
  } else {
    return date.toLocaleDateString('en-IN', {
      day: 'numeric',
      month: 'short',
      year: 'numeric',
    });
  }
};

