import { transferBalance } from '../../src/controllers/paymentController';
import { walletStore } from '../../src/services/walletService';
import { Request, Response } from 'express';

jest.mock('../../src/services/walletService');

describe('Payment Transfer Concurrency - Double Spending Prevention', () => {
  let balances: Record<string, number>;

  beforeEach(() => {
    balances = { user_alice: 100, user_bob: 0 };
    (walletStore.getBalance as jest.Mock).mockImplementation(async (userId: string) => balances[userId] ?? 0);
    (walletStore.setBalance as jest.Mock).mockImplementation(async (userId: string, amount: number) => {
      balances[userId] = amount;
    });
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  it('ensures only one of multiple concurrent requests succeeds when funds are limited', async () => {
    const createMockReqRes = () => {
      const req = { body: { senderId: 'user_alice', recipientId: 'user_bob', amount: 60 } } as Request;
      const res = {
        statusCode: 200,
        jsonPayload: null as any,
        status(code: number) {
          this.statusCode = code;
          return this;
        },
        json(data: any) {
          this.jsonPayload = data;
          return this;
        },
      } as unknown as Response & { statusCode: number; jsonPayload: any };
      return { req, res };
    };

    const invocations = Array.from({ length: 5 }, () => createMockReqRes());
    await Promise.all(invocations.map(({ req, res }) => transferBalance(req, res)));

    const successful = invocations.filter(({ res }) => res.statusCode === 200);
    const failed = invocations.filter(({ res }) => res.statusCode === 402);

    expect(successful).toHaveLength(1);
    expect(failed).toHaveLength(4);
    expect(balances.user_alice).toBe(40);
    expect(balances.user_bob).toBe(60);
  });
});

