import { transferBalance } from '../../src/controllers/paymentController';
import { walletStore } from '../../src/services/walletService';
import { Request, Response } from 'express';

jest.mock('../../src/services/walletService');

describe('Payment Transfer Concurrency - Lock Release on Error', () => {
  let balances: Record<string, number>;

  beforeEach(() => {
    balances = { user_alice: 100, user_bob: 0 };
    (walletStore.getBalance as jest.Mock).mockImplementation(async (userId: string) => balances[userId] ?? 0);
    (walletStore.setBalance as jest.Mock).mockImplementation(async (userId: string, amount: number) => {
      balances[userId] = amount;
    });
  });

  it('releases lock when ledger store throws an error, allowing subsequent transactions', async () => {
    const createMockReqRes = (amount: number) => {
      const req = { body: { senderId: 'user_alice', recipientId: 'user_bob', amount } } as Request;
      const res = {
        statusCode: 200,
        jsonPayload: null as any,
        status(code: number) {
          this.statusCode = code;
          return this;
        },
        json(data: any) {
          this.jsonPayload = data;
          return this;
        },
      } as unknown as Response & { statusCode: number; jsonPayload: any };
      return { req, res };
    };

    // Force setBalance to throw on the first transfer attempt
    (walletStore.setBalance as jest.Mock).mockRejectedValueOnce(new Error('Database disk full'));

    const firstAttempt = createMockReqRes(30);
    await transferBalance(firstAttempt.req, firstAttempt.res);
    expect(firstAttempt.res.statusCode).toBe(500);
    expect(firstAttempt.res.jsonPayload.error).toContain('Failed to commit ledger entry');

    // Verify subsequent transfer executes and does not deadlock
    const secondAttempt = createMockReqRes(30);
    await transferBalance(secondAttempt.req, secondAttempt.res);

    expect(secondAttempt.res.statusCode).toBe(200);
    expect(balances.user_alice).toBe(70);
    expect(balances.user_bob).toBe(30);
  });
});

