  let unhandledRejectionListener: jest.Mock;

  beforeEach(() => {
    errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
    unhandledRejectionListener = jest.fn();
    process.on('unhandledRejection', unhandledRejectionListener);
  });

  afterEach(() => {
    process.off('unhandledRejection', unhandledRejectionListener);
    errorSpy.mockRestore();
    jest.restoreAllMocks();
  });

  it('catches and logs errors if processWebhookEventAsync encounters an unexpected internal failure', async () => {
    const event = {
      type: 'payment_intent.succeeded',
      get data() {
        throw new Error('Database connection reset during payload parsing');
      }
    };

    webhookService.handleIncomingWebhook(event);

    await new Promise((resolve) => setTimeout(resolve, 50));

    expect(unhandledRejectionListener).not.toHaveBeenCalled();
    expect(errorSpy).toHaveBeenCalledWith(expect.stringContaining('[Webhook] Asynchronous processing error: Database connection reset during payload parsing'));
  });
});

import { handleIncomingWebhook } from '../../src/services/webhookService';

describe('Webhook Service - Concurrency & Boundary Resilience', () => {
  let warnSpy: jest.SpyInstance;
  let errorSpy: jest.SpyInstance;
  let unhandledRejectionListener: jest.Mock;

  beforeEach(() => {
    warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});
    errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
    unhandledRejectionListener = jest.fn();
    process.on('unhandledRejection', unhandledRejectionListener);
  });

  afterEach(() => {
    process.off('unhandledRejection', unhandledRejectionListener);
    warnSpy.mockRestore();
    errorSpy.mockRestore();
  });

  it('handles burst of 50 concurrent mixed valid, malformed, and undefined webhooks', async () => {
    const payloads = Array.from({ length: 50 }, (_, i) => {
      if (i % 3 === 0) return null;
      if (i % 3 === 1) return { invalidField: true };
      return { type: 'payment_intent.succeeded', data: { id: `evt_${i}`, amount: 1000 } };
    });

    payloads.forEach((payload) => {
      handleIncomingWebhook(payload);
    });

    await new Promise((resolve) => setTimeout(resolve, 100));

    expect(unhandledRejectionListener).not.toHaveBeenCalled();
    expect(warnSpy.mock.calls.length).toBeGreaterThan(0);
  });
});

