import { walletStore } from '../stores/walletStore';
import { transferController } from './paymentController';

describe('Balance Transfer Concurrency', () => {
  it('should ensure only one transfer succeeds when balance is insufficient for multiple', async () => {
    const senderId = 'user_1';
    const recipientId = 'user_2';
    await walletStore.setBalance(senderId, 100);

    // Attempt 5 concurrent transfers of 60 each (Total 300, but only 100 available)
    const results = await Promise.allSettled([
      transferController.transfer(senderId, recipientId, 60),
      transferController.transfer(senderId, recipientId, 60),
      transferController.transfer(senderId, recipientId, 60),
      transferController.transfer(senderId, recipientId, 60),
      transferController.transfer(senderId, recipientId, 60)
    ]);

    const finalBalance = await walletStore.getBalance(senderId);
    const successful = results.filter(r => r.status === 'fulfilled');

    expect(successful.length).toBe(1);
    expect(finalBalance).toBe(40);
  });
});

