  it('should reject negative transfer amounts', async () => {
    await expect(transferController.transfer('u1', 'u2', -50)).rejects.toThrow('Invalid amount');
  });

  it('should reject transfer if sender account does not exist', async () => {
    await expect(transferController.transfer('non_existent', 'u2', 10)).rejects.toThrow('Account not found');
  });
});

